    "context": "Neste capítulo longo e deliberadamente chocante, Deus conta a história de Jerusalém como uma alegoria: uma criança recém-nascida abandonada e desprezada, que o Senhor resgata, cria e, ao chegar à idade adulta, desposa, cobrindo-a de honra e riqueza. Mas a cidade toma os próprios dons recebidos e os usa para se prostituir atrás de ídolos e nações estrangeiras, numa traição que a linguagem do texto descreve com intencional crueza para transmitir a gravidade do rompimento de aliança. Ainda assim, o capítulo termina não em condenação final, mas na promessa surpreendente de uma aliança eterna.",
