          "n": 24,
          "text": "\"Portanto, assim diz o Soberano Senhor: ‘Visto que vocês trouxeram à lembrança a sua iniqüidade mediante rebelião ostensiva, revelando seus pecados em tudo o que fazem; porque vocês fizeram isso, serão levados prisioneiros."
