    "context": "Ezequiel é conduzido por um rio que brota de debaixo do limiar do templo, crescendo progressivamente — até os tornozelos, os joelhos, a cintura, e finalmente um rio impossível de atravessar a não ser a nado — simbolizando que a presença de Deus produz vida em abundância crescente e incontrolável. Esse rio flui para o leste, em direção ao Mar Morto, e sara suas águas, trazendo vida onde antes só havia esterilidade; árvores frutíferas nas margens produzem fruto continuamente, com folhas medicinais. O capítulo encerra com a delimitação das fronteiras da terra restaurada, incluindo, notavelmente, a inclusão dos estrangeiros residentes como herdeiros junto com as tribos.",
